"use client";

import { HStack, Loader } from "@chakra-ui/react"

export const LoaderBasic = () => {
  return (
    <HStack textStyle="sm" fontWeight="medium">
      <Loader text="Loading...">Click me</Loader>
    </HStack>
  )
}

"use client";

import { Badge, Loader } from "@chakra-ui/react"

export const LoaderWithBadge = () => {
  return (
    <Badge>
      <Loader text="Loading...">Click me</Loader>
    </Badge>
  )
}

"use client";

import { LoaderBasic as Example } from "@/components/rendyn-libraries/chakra/upstream/examples/loader-basic";
import { ChakraProvider, defaultSystem } from "@chakra-ui/react";

export default function Preview() {

  return <div style={{ width: "100%", maxWidth: "48rem", padding: "1.5rem" }}><ChakraProvider value={defaultSystem}><Example /></ChakraProvider></div>;
}

